const AWADHI_STATS=[{label:"Speakers",value:"~38 Million"},{label:"Language Family",value:"Indo-Aryan"},{label:"Script",value:"Devanagari"},{label:"Primary Region",value:"Awadh, Uttar Pradesh"}],AWADHI_GREETING={devanagari:"प्रणाम",transliteration:"Praṇām",meaning:"The standard respectful greeting used across the Awadhi-speaking region, used for both hello and goodbye, especially with elders — shared broadly with Hindi and other Gangetic-plain languages.",folkVariant:{devanagari:"राम राम",transliteration:"Rām Rām",meaning:"An extremely common everyday greeting throughout the Awadh region, invoking Lord Ram — reflecting Awadh's deep cultural association as the traditional homeland of the Ramayana narrative."},note:"Awadhi does not have a dedicated browser text-to-speech voice, so pronunciation below plays using the closest available Hindi (Devanagari-script) voice as an approximation — not a native Awadhi recording. Actual Awadhi speech has its own distinct rhythm and vowel quality."},AWADHI_WORDS=[{devanagari:"पानी",translit:"Pānī",meaning:"Water",note:"Shared Indo-Aryan root with Hindi; pronunciation softens slightly in rural Awadhi speech."},{devanagari:"नीक",translit:"Nīk",meaning:"Good / Nice",note:"A regional term for 'good', also found in several other Eastern Hindi belt languages, distinct from standard Hindi 'accha'."},{devanagari:"घर",translit:"Ghar",meaning:"House / Home",note:"Common Indo-Aryan vocabulary shared across most languages of the Gangetic plain."},{devanagari:"अम्मा",translit:"Ammā",meaning:"Mother",note:"A widely used affectionate term for mother across Awadh, alongside 'माई' (Māī)."},{devanagari:"बाबा",translit:"Bābā",meaning:"Father / Grandfather",note:"Used for father in some Awadhi-speaking families and for grandfather in others, depending on local dialect variation."},{devanagari:"कईसे",translit:"Kaīse",meaning:"How",note:"The Awadhi form of Hindi 'kaise', reflecting characteristic vowel shifts of the dialect."},{devanagari:"खाना",translit:"Khānā",meaning:"Food / To eat",note:"Shared root with Hindi and neighboring Indo-Aryan languages of the region."},{devanagari:"दिन",translit:"Din",meaning:"Day",note:"Common Indo-Aryan vocabulary tracing back to Sanskrit 'dina'."},{devanagari:"इहाँ",translit:"Ihā̃",meaning:"Here",note:"A distinctly Awadhi locative form, differing from standard Hindi 'yahan'."},{devanagari:"जल्दी",translit:"Jaldī",meaning:"Quickly",note:"Shared across neighboring Indo-Aryan languages, used identically in everyday Awadhi speech."}],AWADHI_SCRIPT={intro:"Awadhi is written in the Devanagari script, the same script used for Hindi and Sanskrit, which has made its major literary works widely accessible to readers across the Hindi-speaking belt.",facts:[{title:"Devanagari Standard",detail:"Modern printed Awadhi literature, from classical epics to contemporary folk collections, uses standard Devanagari, aiding readability alongside Hindi."},{title:"Persianized Vocabulary Layer",detail:"Centuries of Awadh's role as a regional political and cultural center, especially under the Nawabs of Awadh, left a layer of Persian and Urdu loanwords within everyday Awadhi speech."},{title:"Dialectal Variation",detail:"Awadhi varies noticeably between its eastern and western sub-regions, with differences in vocabulary and verb forms across districts of the historical Awadh region."}]},AWADHI_CLASSIFICATION={family:"Indo-European → Indo-Iranian → Indo-Aryan → Central Zone (Eastern Hindi group)",siblings:["Bagheli","Chhattisgarhi","Standard Hindi (as a literary register)"],note:"Awadhi belongs to the Eastern Hindi group of Central Zone Indo-Aryan languages, distinct from the Western Hindi group that gave rise to Khariboli, the base of modern Standard Hindi. Despite this, Awadhi is often popularly treated as a dialect of Hindi due to shared script and centuries of literary interaction."},AWADHI_REGION={intro:"Awadhi is spoken primarily across the historical Awadh region of central Uttar Pradesh, an area whose cultural and political importance stretches from the era of the Kosala kingdom of the Ramayana through the Nawabi period of Lucknow.",districts:["Lucknow","Ayodhya (Faizabad)","Sultanpur","Barabanki","Raebareli","Amethi","Pratapgarh","Unnao","Gonda"]},AWADHI_LITERATURE=[{title:"Ramcharitmanas — Goswami Tulsidas",period:"16th century CE",desc:"Awadhi's single most celebrated literary work, Tulsidas's retelling of the Ramayana in Awadhi verse remains one of the most widely read and recited religious texts in North India, cementing Awadhi's status as a major literary language independent of Sanskrit."},{title:"Padmavat — Malik Muhammad Jayasi",period:"16th century CE",desc:"A landmark Sufi romantic epic composed in Awadhi, blending Indian folk narrative with Sufi allegory — considered one of the finest examples of pre-modern Awadhi poetry outside the Ramcharitmanas tradition."},{title:"Awadhi Folk Songs & Sohar",period:"Ongoing oral tradition",desc:"Awadh has a deep tradition of orally transmitted folk songs, including Sohar (birth songs), Kajari (monsoon songs), and wedding songs, still performed at community celebrations across the region today."}],AWADHI_CULTURE=[{title:"Homeland of the Ramayana Narrative",desc:"Ayodhya, the traditional birthplace of Lord Ram, lies at the heart of the Awadh region, giving Awadhi culture and its literature a deep and continuing association with the Ramayana tradition."},{title:"Nawabi Cultural Heritage",desc:"Lucknow's era as the seat of the Nawabs of Awadh left a lasting layer of refined language, etiquette (Lucknowi tehzeeb), and Persian-influenced vocabulary within regional Awadhi speech."},{title:"Continuing Oral Tradition",desc:"Beyond its classical literature, Awadhi remains a living spoken language in rural Uttar Pradesh, sustained through everyday conversation, folk performance, and regional media."}],AWADHI_REFERENCES=[{text:"Grierson, George A. Linguistic Survey of India, Vol. IX: Indo-Aryan Family, Central Group. 1916.",url:"https://archive.org/"},{text:"Saksena, Baburam. Evolution of Awadhi: A Branch of Hindi. Indian Press, 1937.",url:"https://www.jstor.org/"},{text:"Census of India — Statement of Language and Mother Tongue Strength.",url:"https://censusindia.gov.in/"},{text:"People's Linguistic Survey of India (PLSI) — Awadhi Volume.",url:"https://peopleslinguisticsurvey.org/"}];